namespace ClearSpace {
public sealed class CleanerSettings {
 public string UpdateUrl="",RecoveryDirectory="";public bool AutomaticUpdates,UseWinapp2=true;public string LastUpdateAttempt="",LastWinapp2Attempt="";public List<string> PortableDirectories=new List<string>();
 public static string Root{get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ClearSpace");}}
 public static CleanerSettings Load(){try{var s=new JavaScriptSerializer().Deserialize<CleanerSettings>(File.ReadAllText(Path.Combine(Root,"settings.json")))??new CleanerSettings();s.UpdateUrl=s.UpdateUrl??"";s.RecoveryDirectory=s.RecoveryDirectory??"";s.LastUpdateAttempt=s.LastUpdateAttempt??"";s.PortableDirectories=(s.PortableDirectories??new List<string>()).Where(p=>!String.IsNullOrWhiteSpace(p)&&Regex.IsMatch(p,"^[a-zA-Z]:\\\\")).Distinct(StringComparer.OrdinalIgnoreCase).Take(30).ToList();if(s.RecoveryDirectory.Length>0&&!Regex.IsMatch(s.RecoveryDirectory,"^[a-zA-Z]:\\\\"))s.RecoveryDirectory="";return s;}catch{return new CleanerSettings();}}
 public void Save(){AtomicFile.Write(Path.Combine(Root,"settings.json"),new JavaScriptSerializer().Serialize(this));}
}
public static class AtomicFile {
 public static void Write(string path,string text){string directory=Path.GetDirectoryName(Path.GetFullPath(path));Directory.CreateDirectory(directory);if(!Engine.SafeAncestors(Path.Combine(directory,"probe")))throw new IOException("保存目录包含链接或无法验证");string tmp=Path.Combine(directory,Guid.NewGuid().ToString("N")+".tmp");try{using(var stream=new FileStream(tmp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] data=Encoding.UTF8.GetBytes(text);stream.Write(data,0,data.Length);stream.Flush(true);}if(File.Exists(path)){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("拒绝覆盖链接文件");File.Replace(tmp,path,null);}else File.Move(tmp,path);}finally{if(File.Exists(tmp))File.Delete(tmp);}}
}
public sealed class ApplicationRule {
 public string Id,Name,Group="软件缓存",Part="资源缓存",Description,Impact,FileNameRegex,Method="files";
 public string[] MatchNames,ExecutableNames,Publishers,ProductNames,Paths,ExcludePaths,ExcludeNames,Extensions;public bool RequireSignature;public int KeepDays=14;
}
public sealed class ApplicationRulePack {public int Schema=1;public string Version="3.0.0",Published;public List<ApplicationRule> Rules=new List<ApplicationRule>();}
public sealed class SignedRuleEnvelope {public string Payload,Signature;}
public sealed class LoadedRulePack {public ApplicationRulePack Pack;public string Trust,Raw;}
public sealed class RuleStore {
 static readonly object MutationGate=new object();
 public string DirectoryPath;public string PublicKey;public const int MaxBytes=3*1024*1024;
 public RuleStore(string directory=null,string publicKey=null){DirectoryPath=directory??Path.Combine(CleanerSettings.Root,"Rules");PublicKey=publicKey??ReadResource("ClearSpace.rule-public-key.xml");}
 static string ReadResource(string name){using(var s=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream(name)){if(s==null)return null;using(var r=new StreamReader(s))return r.ReadToEnd();}}
 public LoadedRulePack Read(string text,bool allowUnsigned){if(Encoding.UTF8.GetByteCount(text)>MaxBytes)throw new InvalidDataException("规则包超过 3 MB");var json=new JavaScriptSerializer{MaxJsonLength=MaxBytes};ApplicationRulePack pack;string trust;
  var envelope=json.Deserialize<SignedRuleEnvelope>(text);if(envelope!=null&&!String.IsNullOrEmpty(envelope.Payload)){byte[] data=Convert.FromBase64String(envelope.Payload),signature=Convert.FromBase64String(envelope.Signature??"");if(data.Length>MaxBytes||String.IsNullOrEmpty(PublicKey))throw new InvalidDataException("签名配置无效");using(var rsa=new RSACryptoServiceProvider()){rsa.PersistKeyInCsp=false;rsa.FromXmlString(PublicKey);if(!rsa.VerifyData(data,CryptoConfig.MapNameToOID("SHA256"),signature))throw new InvalidDataException("规则签名校验失败，当前规则保留");}pack=json.Deserialize<ApplicationRulePack>(Encoding.UTF8.GetString(data));trust="发布者签名已验证";}else{if(!allowUnsigned)throw new InvalidDataException("云更新仅接受发布者签名包");pack=json.Deserialize<ApplicationRulePack>(text);trust="本地导入 · 未签名";}
  Validate(pack);return new LoadedRulePack{Pack=pack,Trust=trust,Raw=text};
 }
 public static void Validate(ApplicationRulePack pack){
  Version version;if(pack==null||pack.Schema!=1||!Version.TryParse(pack.Version,out version)||pack.Rules==null||pack.Rules.Count>500)throw new InvalidDataException("规则格式或版本无效");var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  foreach(var r in pack.Rules){
   if(r==null||!Regex.IsMatch(r.Id??"","^[a-z0-9][a-z0-9-]{1,79}$")||!ids.Add(r.Id)||String.IsNullOrWhiteSpace(r.Name)||r.Name.Length>100||r.Paths==null||r.Paths.Length==0||r.Paths.Length>30||r.KeepDays<7||r.KeepDays>3650||!new[]{"软件缓存","网页缓存","开发缓存"}.Contains(r.Group)||!new[]{"files","contents"}.Contains(r.Method)||((r.MatchNames??new string[0]).Length==0&&(r.ExecutableNames??new string[0]).Length==0))throw new InvalidDataException("规则字段、范围或保留期无效");
   foreach(var terms in new[]{r.MatchNames,r.ExecutableNames,r.Publishers,r.ProductNames,r.ExcludeNames,r.Extensions})if(terms!=null&&(terms.Length>64||terms.Any(t=>String.IsNullOrWhiteSpace(t)||t.Length>200)))throw new InvalidDataException("指纹及排除条件不可为空或过长");
   if((r.ExecutableNames??new string[0]).Any(n=>n.IndexOfAny(new[]{'\\','/',':','*','?'})>=0||!n.EndsWith(".exe",StringComparison.OrdinalIgnoreCase)))throw new InvalidDataException("程序指纹必须是明确的 EXE 文件名");
   if((r.ExcludePaths??new string[0]).Length>100)throw new InvalidDataException("排除路径过多");
   foreach(string path in r.Paths)PathPolicy.ValidateTemplate(path);foreach(string path in r.ExcludePaths??new string[0])PathPolicy.ValidateTemplate(path,false);
   if(!String.IsNullOrEmpty(r.FileNameRegex)){if(r.FileNameRegex.Length>256)throw new InvalidDataException("正则过长");new Regex(r.FileNameRegex,RegexOptions.IgnoreCase,TimeSpan.FromMilliseconds(100));}
   if((r.Extensions??new string[0]).Any(e=>!Regex.IsMatch(e,"^\\.[a-zA-Z0-9]{1,12}$")))throw new InvalidDataException("扩展名无效");
  }
 }
 public LoadedRulePack Current(){foreach(string name in new[]{"active.json","previous.json"})try{string file=Path.Combine(DirectoryPath,name);if(File.Exists(file))return Read(File.ReadAllText(file),true);}catch{}string embedded=ReadResource("ClearSpace.BundledRules.signed.json");if(embedded!=null)return Read(embedded,false);return new LoadedRulePack{Pack=Defaults(),Trust="内置规则",Raw=new JavaScriptSerializer().Serialize(Defaults())};}
 public LoadedRulePack Import(string text,bool local){lock(MutationGate){var pack=Read(text,local);if(!local&&new Version(pack.Pack.Version)<=new Version(Current().Pack.Version))throw new InvalidDataException("云端版本没有更新，当前规则保留");string active=Path.Combine(DirectoryPath,"active.json"),previous;if(File.Exists(active)){previous=File.ReadAllText(active);Read(previous,true);}else{try{previous=Current().Raw;}catch{previous=new JavaScriptSerializer().Serialize(Defaults());}}AtomicFile.Write(Path.Combine(DirectoryPath,"previous.json"),previous);AtomicFile.Write(active,text);return pack;}}
 public LoadedRulePack Rollback(){lock(MutationGate){string file=Path.Combine(DirectoryPath,"previous.json");if(!File.Exists(file))throw new IOException("暂无上一版本");string text=File.ReadAllText(file);var pack=Read(text,true);AtomicFile.Write(Path.Combine(DirectoryPath,"active.json"),text);return pack;}}
 public LoadedRulePack Update(string url,CancellationToken token){Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri)||uri.Scheme!=Uri.UriSchemeHttps||!String.IsNullOrEmpty(uri.UserInfo))throw new InvalidDataException("请输入不含账号信息的 HTTPS 规则文件地址");ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var request=(HttpWebRequest)WebRequest.Create(uri);request.AllowAutoRedirect=false;request.Timeout=15000;request.ReadWriteTimeout=15000;request.UserAgent="ClearSpace/"+ReleaseVersion.Display+ReleaseVersion.Display+" Rules";using(token.Register(()=>request.Abort()))using(var response=(HttpWebResponse)request.GetResponse()){if(response.StatusCode!=HttpStatusCode.OK||response.ContentLength>MaxBytes)throw new IOException("规则下载响应无效");using(var stream=response.GetResponseStream())using(var memory=new MemoryStream()){byte[] buffer=new byte[16384];int count;while((count=stream.Read(buffer,0,buffer.Length))>0){token.ThrowIfCancellationRequested();if(memory.Length+count>MaxBytes)throw new InvalidDataException("规则包过大");memory.Write(buffer,0,count);}token.ThrowIfCancellationRequested();return Import(Encoding.UTF8.GetString(memory.ToArray()),false);}}}
 public static ApplicationRulePack Defaults(){var pack=new ApplicationRulePack{Published="2026-10-13"};string[] apps={"chrome|Google Chrome|chrome.exe|Google Chrome|Google\\Chrome\\User Data", "edge|Microsoft Edge|msedge.exe|Microsoft Edge|Microsoft\\Edge\\User Data", "brave|Brave|brave.exe|Brave|BraveSoftware\\Brave-Browser\\User Data", "vivaldi|Vivaldi|vivaldi.exe|Vivaldi|Vivaldi\\User Data"};foreach(string spec in apps){var p=spec.Split('|');pack.Rules.Add(new ApplicationRule{Id=p[0]+"-offline-cache",Name=p[1],Group="网页缓存",Part="离线网页缓存",MatchNames=new[]{p[1]},ExecutableNames=new[]{p[2]},ProductNames=new[]{p[3]},Paths=new[]{"%LOCALAPPDATA%\\"+p[4]+"\\*\\Service Worker\\CacheStorage","%EXEDIR%\\User Data\\*\\Cache","%EXEDIR%\\Data\\*\\Cache"},KeepDays=30,Description="已识别浏览器的离线/便携资源缓存。",Impact="离线网页或资源可能失效，需要重新下载；保留账号、数据库与会话。"});}
  string[] portable={"vscode|Visual Studio Code|Code.exe|Code", "obsidian|Obsidian|Obsidian.exe|obsidian", "discord|Discord|Discord.exe|discord", "notion|Notion|Notion.exe|Notion", "postman|Postman|Postman.exe|Postman", "insomnia|Insomnia|Insomnia.exe|Insomnia", "figma|Figma|Figma.exe|Figma", "githubdesktop|GitHub Desktop|GitHubDesktop.exe|GitHub Desktop", "slack|Slack|slack.exe|Slack", "signal|Signal|Signal.exe|Signal", "telegram|Telegram|Telegram.exe|Telegram Desktop"};foreach(string spec in portable){var p=spec.Split('|');pack.Rules.Add(new ApplicationRule{Id=p[0]+"-portable",Name=p[1],MatchNames=new[]{p[1]},ExecutableNames=new[]{p[2]},Paths=new[]{"%EXEDIR%\\data\\Cache","%EXEDIR%\\data\\GPUCache","%EXEDIR%\\data\\Code Cache","%EXEDIR%\\Data\\"+p[3]+"\\Cache","%EXEDIR%\\Data\\"+p[3]+"\\GPUCache","%INSTALLDIR%\\Cache","%INSTALLDIR%\\GPUCache"},ExcludeNames=PathPolicy.SensitiveNames,KeepDays=30,Description="按应用指纹匹配的便携或自定义资源缓存。",Impact="资源需重新生成；不处理配置、账号、聊天或未保存资料。"});}
  foreach(var rule in pack.Rules){rule.Paths=rule.Paths.Concat(rule.Group=="网页缓存"?new[]{"%PORTABLEROOT%\\Data\\profile\\*\\Cache","%PORTABLEROOT%\\Data\\profile\\*\\GPUCache","%PORTABLEROOT%\\Data\\profile\\*\\Code Cache"}:new[]{"%PORTABLEROOT%\\Data\\Cache","%PORTABLEROOT%\\Data\\GPUCache","%PORTABLEROOT%\\Data\\Code Cache"}).ToArray();}
  return pack;
 }
 public List<Rule> Resolve(LoadedRulePack pack,DiscoveryResult discovery){var rules=new List<Rule>();foreach(var definition in pack.Pack.Rules){var apps=discovery.Applications.Where(a=>MatchesDefinition(definition,a)).ToList();if(apps.Count==0)continue;var roots=new List<string>();var exclusions=new List<string>();foreach(var app in apps){foreach(string path in definition.Paths)roots.AddRange(PathPolicy.Resolve(path,app));foreach(string path in definition.ExcludePaths??new string[0])exclusions.AddRange(PathPolicy.Resolve(path,app,false));}roots=roots.Where(p=>Directory.Exists(p)&&PathPolicy.AllowedCacheRoot(p)).Distinct(StringComparer.OrdinalIgnoreCase).Take(100).ToList();if(roots.Count==0)continue;var owners=apps.Select(a=>Path.GetFileNameWithoutExtension(a.Executable)).Where(s=>!String.IsNullOrEmpty(s)).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();var rule=new Rule("library-"+definition.Id,definition.Name+" "+definition.Part,definition.Group,definition.Description??"外部路径规则",definition.Impact??"需自行确认缓存用途",roots.ToArray(),definition.KeepDays,false,owners){Software=definition.Name,Part=definition.Part??"规则库缓存",GroupOverride=definition.Group,AllowManual=true,Extensions=definition.Extensions,ExcludedRoots=exclusions.ToArray(),ExcludedNames=(definition.ExcludeNames??new string[0]).Concat(PathPolicy.SensitiveNames).Distinct(StringComparer.OrdinalIgnoreCase).ToArray(),FileNameRegex=definition.FileNameRegex,Detection="规则库 "+pack.Pack.Version+" · "+pack.Trust+"\n"+String.Join("\n",apps.Take(3).Select(Describe))};rules.Add(rule);}return rules;}
 public static string Describe(ApplicationIdentity a){return a.Name+" · "+a.Version+" · "+a.Signature+(String.IsNullOrEmpty(a.Signer)?"":" / "+a.Signer)+"\n来源："+a.Evidence+"\n程序："+a.Executable;}
 public static bool MatchesDefinition(ApplicationRule rule,ApplicationIdentity app){return ApplicationDiscovery.Matches(app,rule.MatchNames,rule.ExecutableNames,rule.Publishers)&&((rule.ProductNames??new string[0]).Length==0||rule.ProductNames.Any(p=>String.Equals(app.Product,p,StringComparison.OrdinalIgnoreCase)))&&(!rule.RequireSignature||app.Signature=="签名验证通过");}
}
public static class PathPolicy {
 public static readonly string[] SensitiveNames={"Cookies","Login Data","History","Web Data","Preferences","Secure Preferences","Bookmarks","Local State","Local Storage","Session Storage","IndexedDB","Sessions","Backups","User","LocalHistory","config","settings","accounts","databases","wallet","vault","keychain","credentials","chats","messages"};
 static readonly string[] CacheNames={"Cache","Caches","Code Cache","GPUCache","DawnCache","DawnGraphiteCache","DawnWebGPUCache","ShaderCache","CacheStorage","Crashpad","CrashDumps","Crash Reports","logs","log","tmp","temp","cache2","go-build","_cacache"};
 public static bool CacheName(string name){return CacheNames.Contains(name,StringComparer.OrdinalIgnoreCase);}
 public static void ValidateTemplate(string path,bool requireCache=true){if(String.IsNullOrWhiteSpace(path)||path.Length>512||path.IndexOfAny(new[]{':','/','\0'})>=0||path.Contains("..")||!Regex.IsMatch(path,"^%(LOCALAPPDATA|APPDATA|PROGRAMDATA|TEMP|INSTALLDIR|EXEDIR|PORTABLEROOT)%\\\\[^%]+$",RegexOptions.IgnoreCase)||path.Split('\\').Skip(1).Any(s=>String.IsNullOrEmpty(s)||s.Contains("**")))throw new InvalidDataException("规则路径必须使用支持的环境/应用变量，禁止越界与任意绝对路径");if(requireCache&&!path.Split('\\').Skip(1).Any(CacheName))throw new InvalidDataException("规则只允许明确缓存、临时或日志目录");}
 public static bool AllowedCacheRoot(string path){try{string p=Path.GetFullPath(path),data=Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData);string[] protectedRoots={Environment.GetFolderPath(Environment.SpecialFolder.Windows),Path.Combine(data,"Microsoft","Windows"),Path.Combine(data,"Package Cache"),Path.Combine(data,"Microsoft","Windows Defender"),Path.Combine(RuleBook.TargetDrive,"Recovery"),Path.Combine(RuleBook.TargetDrive,"$Recycle.Bin"),CleanerSettings.Root};return p.StartsWith(RuleBook.TargetDrive,StringComparison.OrdinalIgnoreCase)&&p.Split('\\').Any(CacheName)&&!protectedRoots.Any(r=>p.Equals(r,StringComparison.OrdinalIgnoreCase)||p.StartsWith(r+"\\",StringComparison.OrdinalIgnoreCase))&&Engine.SafeAncestors(Path.Combine(p,"probe"));}catch{return false;}}
 public static IEnumerable<string> Resolve(string template,ApplicationIdentity app,bool requireCache=true){ValidateTemplate(template,requireCache);int end=template.IndexOf('%',1);string key=template.Substring(1,end-1).ToUpperInvariant(),root=key=="LOCALAPPDATA"?Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData):key=="APPDATA"?Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData):key=="PROGRAMDATA"?Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData):key=="TEMP"?Path.GetTempPath():key=="INSTALLDIR"?app.InstallDirectory:key=="PORTABLEROOT"?app.PortableRoot:Path.GetDirectoryName(app.Executable);if(String.IsNullOrWhiteSpace(root)||!Directory.Exists(root))return new string[0];return CatalogV2.Expand(root,template.Substring(end+2)).Where(p=>!requireCache||AllowedCacheRoot(p)).ToArray();}
 public static bool Sensitive(string path,string root){string relative=Path.GetFullPath(path).Substring(Engine.Normalize(root).Length).TrimStart('\\');return relative.Split('\\').Any(p=>SensitiveNames.Any(n=>p.Equals(n,StringComparison.OrdinalIgnoreCase)||p.StartsWith(n+"-",StringComparison.OrdinalIgnoreCase)||p.StartsWith(n+".",StringComparison.OrdinalIgnoreCase)))||new[]{".doc",".docx",".xls",".xlsx",".ppt",".pptx",".pdf",".kdbx",".sqlite",".sqlite3",".db",".mdb",".pst",".ost",".pem",".key",".pfx",".ini",".config",".json",".yaml",".yml",".xml"}.Contains(Path.GetExtension(path),StringComparer.OrdinalIgnoreCase);}
}
